import { test } from 'node:test';
import assert from 'node:assert/strict';
import { copyItems } from '../src/items.ts';
test('copy preserves input and order', () => {
 const input = Object.freeze(['b', 'a']);
 assert.deepEqual(copyItems(input), ['b', 'a']);
 assert.notEqual(copyItems(input), input);
});

import { limitItems } from '../src/items.ts';
test('limits retain order; zero is unlimited; negatives throw', () => {
 const values = Object.freeze(['c', 'a', 'b']);
 assert.deepEqual(limitItems(values, 0), ['c', 'a', 'b']);
 assert.deepEqual(limitItems(values, 2), ['c', 'a']);
 assert.throws(() => limitItems(values, -1), RangeError);
});

